;(()=>{
  const SUPABASE_URL = "https://nwvcvtoiosozziaqemtk.supabase.co";
  const SUPABASE_KEY = "sb_publishable_o_kYS6hzptz4S_n2HG0LxA_tJPiHCKf";
  const CARD_ID = "mgg-top-global-supabase-card";
  const STYLE_ID = "mgg-top-global-supabase-style";
  const routes = ["/perfil", "/comunidad"];

  function currentRoute() {
    const hash = (window.location.hash || "").replace(/^#/, "");
    const path = window.location.pathname || "";
    return hash || path;
  }

  function shouldShow() {
    const route = currentRoute().toLowerCase();
    return routes.some(r => route.includes(r));
  }

  function ensureStyle() {
    if (document.getElementById(STYLE_ID)) return;
    const style = document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = `
      #${CARD_ID} {
        width: min(100%, 1300px);
        margin: 22px auto;
        padding: 22px;
        border-radius: 24px;
        border: 1px solid rgba(59,130,246,.22);
        background: linear-gradient(135deg, rgba(8,16,32,.96), rgba(10,24,48,.92));
        box-shadow: 0 24px 60px rgba(0,0,0,.28);
        color: white;
        font-family: Inter, ui-sans-serif, system-ui, sans-serif;
        text-align: left;
      }
      #${CARD_ID} .mggtg-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 14px;
        margin-bottom: 16px;
      }
      #${CARD_ID} .mggtg-title {
        font-weight: 900;
        text-transform: uppercase;
        letter-spacing: .08em;
        font-size: 18px;
      }
      #${CARD_ID} .mggtg-sub {
        color: #94a3b8;
        font-size: 12px;
        margin-top: 4px;
      }
      #${CARD_ID} .mggtg-pill {
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(37,99,235,.16);
        color: #93c5fd;
        border: 1px solid rgba(59,130,246,.22);
        font-size: 11px;
        font-weight: 900;
        text-transform: uppercase;
        white-space: nowrap;
      }
      #${CARD_ID} .mggtg-table-wrap {
        overflow-x: auto;
        border-radius: 18px;
        border: 1px solid rgba(255,255,255,.08);
      }
      #${CARD_ID} table {
        width: 100%;
        border-collapse: collapse;
        min-width: 620px;
      }
      #${CARD_ID} th {
        color: #93c5fd;
        font-size: 11px;
        text-transform: uppercase;
        letter-spacing: .08em;
        padding: 12px;
        background: rgba(255,255,255,.04);
      }
      #${CARD_ID} td {
        padding: 13px 12px;
        border-top: 1px solid rgba(255,255,255,.07);
        font-size: 13px;
      }
      #${CARD_ID} .rank {
        font-weight: 900;
        color: #facc15;
        width: 60px;
      }
      #${CARD_ID} .name {
        font-weight: 900;
        color: white;
      }
      #${CARD_ID} .muted {
        color: #94a3b8;
      }
      #${CARD_ID} .rango {
        display: inline-flex;
        padding: 5px 9px;
        border-radius: 999px;
        background: rgba(34,197,94,.12);
        color: #86efac;
        border: 1px solid rgba(34,197,94,.18);
        font-size: 11px;
        font-weight: 900;
        text-transform: uppercase;
      }
      @media (max-width: 700px) {
        #${CARD_ID} { padding: 16px; margin: 16px auto; border-radius: 18px; }
        #${CARD_ID} .mggtg-head { align-items: flex-start; flex-direction: column; }
      }
    `;
    document.head.appendChild(style);
  }

  async function getTopGlobal() {
    const endpoint = `${SUPABASE_URL}/rest/v1/top_global?select=nombre,exp,lvl,rango&order=exp.desc&limit=15`;
    const res = await fetch(endpoint, {
      headers: {
        apikey: SUPABASE_KEY,
        Authorization: `Bearer ${SUPABASE_KEY}`,
        "Content-Type": "application/json"
      }
    });
    if (!res.ok) {
      const txt = await res.text();
      throw new Error(txt || `HTTP ${res.status}`);
    }
    return await res.json();
  }

  function findContainer() {
    return document.querySelector("#root main") ||
           document.querySelector("#root .py-12") ||
           document.querySelector("#root > div") ||
           document.getElementById("root") ||
           document.body;
  }

  function removeCard() {
    const old = document.getElementById(CARD_ID);
    if (old) old.remove();
  }

  function renderLoading(container) {
    ensureStyle();
    let card = document.getElementById(CARD_ID);
    if (!card) {
      card = document.createElement("section");
      card.id = CARD_ID;
      container.appendChild(card);
    }
    card.innerHTML = `
      <div class="mggtg-head">
        <div>
          <div class="mggtg-title">Top Global</div>
          <div class="mggtg-sub">Ranking conectado a Supabase desde la tabla top_global.</div>
        </div>
        <div class="mggtg-pill">Cargando...</div>
      </div>
      <div class="muted">Consultando jugadores globales...</div>
    `;
  }

  function renderTop(container, rows) {
    ensureStyle();
    let card = document.getElementById(CARD_ID);
    if (!card) {
      card = document.createElement("section");
      card.id = CARD_ID;
      container.appendChild(card);
    }
    const safe = (v) => String(v ?? "").replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[ch]));
    const body = rows.map((row, idx) => `
      <tr>
        <td class="rank">#${idx + 1}</td>
        <td class="name">${safe(row.nombre)}</td>
        <td>${safe(row.lvl ?? 1)}</td>
        <td>${safe(row.exp ?? 0)}</td>
        <td><span class="rango">${safe(row.rango || "gratuito")}</span></td>
      </tr>
    `).join("");
    card.innerHTML = `
      <div class="mggtg-head">
        <div>
          <div class="mggtg-title">Top Global</div>
          <div class="mggtg-sub">Los gladiadores con más experiencia registrados en Supabase.</div>
        </div>
        <div class="mggtg-pill">${rows.length} jugadores</div>
      </div>
      <div class="mggtg-table-wrap">
        <table>
          <thead>
            <tr>
              <th>Posición</th>
              <th>Gladiador</th>
              <th>Nivel</th>
              <th>EXP</th>
              <th>Rango</th>
            </tr>
          </thead>
          <tbody>${body || '<tr><td colspan="5" class="muted">No hay datos en top_global.</td></tr>'}</tbody>
        </table>
      </div>
    `;
  }

  let lastRoute = "";
  let loadedRoute = "";
  async function syncTopGlobal() {
    const route = currentRoute();
    if (!shouldShow()) {
      removeCard();
      lastRoute = route;
      return;
    }
    const container = findContainer();
    if (!container) return;
    if (loadedRoute === route && document.getElementById(CARD_ID)) return;
    loadedRoute = route;
    renderLoading(container);
    try {
      const rows = await getTopGlobal();
      renderTop(container, Array.isArray(rows) ? rows : []);
    } catch (err) {
      const card = document.getElementById(CARD_ID);
      if (card) card.innerHTML = `
        <div class="mggtg-head">
          <div>
            <div class="mggtg-title">Top Global</div>
            <div class="mggtg-sub">No se pudo leer la tabla top_global.</div>
          </div>
          <div class="mggtg-pill">Error</div>
        </div>
        <div class="muted">${String(err.message || err).slice(0, 400)}</div>
      `;
    }
    lastRoute = route;
  }

  window.addEventListener("hashchange", () => setTimeout(syncTopGlobal, 300));
  window.addEventListener("popstate", () => setTimeout(syncTopGlobal, 300));
  document.addEventListener("DOMContentLoaded", () => setTimeout(syncTopGlobal, 800));
  setInterval(syncTopGlobal, 1500);
})();
